+import { create } from "zustand";
+import { persist, createJSONStorage } from "zustand/middleware";
+import { Vector3 } from "three";
+import {
+  FOODS,
+  FAVORITE_FOOD,
+  STAT_META,
+  stageIndexFor,
+  STAGES,
+  unlocksAt,
+  xpForLevel,
+  type AccessoryId,
+  type FoodId,
