  wood: std("#b77b52"),
  woodDark: std("#8a5a3e"),
  barn: std("#f07370", { roughness: 0.7 }),
  barnDark: std("#d35a5d"),
  roof: std("#7a4d63", { roughness: 0.75 }),
  trim: std("#fff6e6"),
  hay: std("#f3cf6e", { roughness: 0.95 }),
  hayDark: std("#dcae4a", { roughness: 0.95 }),
  cushion: std("#ffc3d6", { roughness: 0.9 }),
  blanket: std("#b9a4ff", { roughness: 0.9 }),
