  leaf3: std("#5ab25f", { flatShading: true, roughness: 0.85 }),
  apple: std("#ff5a5f", { roughness: 0.4 }),
  water: std("#7fd6f7", { roughness: 0.08, metalness: 0.15, emissive: "#3fb6e8", emissiveIntensity: 0.18 }),
