    const out: { x: number; z: number; a: number }[] = [];
    const n = 8;
    for (let i = 0; i < n; i++) {
      const th = -1.95 + (i / (n - 1)) * 1.05;
      const R = rimRadius(th) - 0.38;
      out.push({ x: Math.cos(th) * R, z: Math.sin(th) * R, a: th });
    }
    return out;
  }, []);
  return (
    <group>
      {posts.map((p, i) => (
        <group key={i}>
