const mkAct = (kind: ActKind, extra: Partial<Act> = {}): Act => ({
  kind,
  t: 0,
  dur: DUR[kind],
  flags: new Set(),
  last: 0,
  ...extra,
});

const once = (a: Act, key: string) => {
  if (a.flags.has(key)) return false;
  a.flags.add(key);
  return true;
};

const V = () => new Vector3();
const tmpA = V();
const tmpB = V();
const tmpC = V();
const Z = new Vector3(0, 0, 1);

function Patch({ dir, size, material, depth = 0.895 }: { dir: [number, number, number]; size: [number, number]; material: Material; depth?: number }) {
  const { pos, quat } = useMemo(() => {
    const n = new Vector3(...dir).normalize();
    return { pos: n.clone().multiplyScalar(depth), quat: new Quaternion().setFromUnitVectors(Z, n) };
  }, [dir, depth]);
  return (
    <mesh position={pos} quaternion={quat} scale={[size[0], size[1], 0.12]} material={material}>
      <sphereGeometry args={[1, 24, 16]} />
    </mesh>
  );
}

