                      </group>
                      <mesh ref={bind(`eyeHappy${side}`)} material={m.line} position={[0, -0.02, 0.03]}>
                        <torusGeometry args={[0.05, 0.015, 8, 16, Math.PI]} />
                      </mesh>
                      <mesh ref={bind(`eyeClosed${side}`)} material={m.line} position={[0, 0.02, 0.03]} rotation={[0, 0, Math.PI]}>
