                      </mesh>
                      <group ref={bind(`eyeSquint${side}`)} position={[0, 0, 0.03]} scale={[sd, 1, 1]}>
                        <mesh material={m.line} position={[0, 0.019, 0]} rotation={[0, 0, Math.PI / 2 + 0.55]}>
                          <capsuleGeometry args={[0.013, 0.045, 4, 8]} />
