          </mesh>
          {Array.from({ length: 6 }).map((_, i) => {
            const a = (i / 6) * Math.PI * 2;
            return (
              <group key={i}>
                <mesh material={m.gold} position={[Math.cos(a) * 0.2, 0.15, Math.sin(a) * 0.2]}>
