import { useEffect, useMemo, useRef, useState } from "react";
import { useFrame, type ThreeEvent } from "@react-three/fiber";
import { Html } from "@react-three/drei";
import {
  Color,
  MathUtils,
  Mesh,
  MeshBasicMaterial,
  MeshPhysicalMaterial,
  MeshStandardMaterial,
  Object3D,
  Quaternion,
  Vector3,
  type Group,
  type Material,
} from "three";
import { FOODS, stageIndexFor, STAGES, type FoodId, type Reaction } from "../game/content";
import {
  ball,
  BED_POS,
  constrain,
  controls,
  cowEvents,
  drag,
  env,
  forward,
  pet,
  pointer,
  rand,
  ROAM_RADIUS,
  view,
} from "../game/runtime";
import { needOf, useGame } from "../game/store";
import { sfx } from "../game/audio";
import { CONFETTI, emit, HEARTS } from "./fx";
import { heartGeometry, radialTexture } from "./shapes";
import { PetBubble, type Emote } from "../ui/PetBubble";

const damp = MathUtils.damp;
const clamp01 = (v: number) => Math.max(0, Math.min(1, v));
const easeInOut = (x: number) => (x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2);
const easeOutBack = (x: number) => {
  const c1 = 1.7;
  return 1 + (c1 + 1) * Math.pow(x - 1, 3) + c1 * Math.pow(x - 1, 2);
};
const wrap = (a: number) => {
  while (a > Math.PI) a -= Math.PI * 2;
  while (a < -Math.PI) a += Math.PI * 2;
  return a;
};

type ActKind =
  | "eat"
  | "love"
  | "yum"
  | "treat"
  | "spicy"
  | "bleh"
  | "refuse"
  | "boop"
  | "giggle"
  | "dizzy"
  | "oops"
  | "yawn"
  | "moo"
  | "sadmoo"
  | "hop"
  | "spin"
  | "sneeze"
  | "levelup"
  | "shiver"
  | "rinse"
  | "shake"
  | "headbutt"
  | "sniff"
  | "hatch"
  | "look"
  | "stir";

const DUR: Record<ActKind, number> = {
  eat: 1.7,
  love: 2.2,
  yum: 1.2,
  treat: 1.8,
  spicy: 2.6,
  bleh: 1.8,
  refuse: 1.1,
  boop: 0.5,
  giggle: 1.0,
  dizzy: 2.2,
  oops: 1.6,
  yawn: 1.9,
  moo: 1.3,
  sadmoo: 1.9,
  hop: 0.8,
  spin: 1.3,
  sneeze: 1.5,
  levelup: 2.8,
  shiver: 1.2,
  rinse: 2.1,
  shake: 1.4,
  headbutt: 0.45,
  sniff: 2.0,
  hatch: 1.7,
  look: 2.4,
  stir: 0.9,
};

const INTERRUPTIBLE: Partial<Record<ActKind, boolean>> = {
  look: true,
  sniff: true,
  hop: true,
  spin: true,
  moo: true,
  giggle: true,
  boop: true,
  shiver: true,
  sadmoo: true,
};

interface Act {
  kind: ActKind;
  t: number;
  dur: number;
  food?: FoodId;
  ground?: boolean;
  flags: Set<string>;
  last: number;
}

interface Expr {
  eyes: "open" | "happy" | "closed" | "squint";
  lid: number;
  mouth: "smile" | "frown" | "flat";
  open: number;
  tongue: boolean;
  brows: "none" | "sad" | "angry" | "raised";
  blush: number;
  earDroop: number;
  tail: number;
  cheekPuff: number;
  red: number;
}

interface Pose {
  hop: number;
  squash: number;
  roll: number;
  lie: number;
  headDown: number;
  spin: number;
  lunge: number;
  yaw: number;
  pitch: number;
  headRoll: number;
}

const mkAct = (kind: ActKind, extra: Partial<Act> = {}): Act => ({
  kind,
  t: 0,
  dur: DUR[kind],
  flags: new Set(),
  last: 0,
  ...extra,
});

const once = (a: Act, key: string) => {
  if (a.flags.has(key)) return false;
  a.flags.add(key);
  return true;
};

const V = () => new Vector3();
const tmpA = V();
const tmpB = V();
const tmpC = V();
const Z = new Vector3(0, 0, 1);

function Patch({
  dir,
  size,
  material,
  depth = 0.895,
  groupRef,
}: {
  dir: [number, number, number];
  size: [number, number];
  material: Material;
  depth?: number;
  groupRef?: (o: Object3D | null) => void;
}) {
  const { pos, quat } = useMemo(() => {
    const n = new Vector3(...dir).normalize();
    return { pos: n.clone().multiplyScalar(depth), quat: new Quaternion().setFromUnitVectors(Z, n) };
  }, [dir, depth]);
  return (
    <group ref={groupRef} position={pos} quaternion={quat}>
      <mesh scale={[size[0], size[1], 0.12]} material={material}>
        <sphereGeometry args={[1, 24, 16]} />
      </mesh>
    </group>
  );
}

