import { useEffect, useMemo, useRef, useState } from "react";
import { useFrame, type ThreeEvent } from "@react-three/fiber";
import { Html } from "@react-three/drei";
import {
  Color,
  MathUtils,
  Mesh,
  MeshBasicMaterial,
  MeshPhysicalMaterial,
  MeshStandardMaterial,
  Object3D,
  Quaternion,
  Vector3,
  type Group,
  type Material,
} from "three";
import { FOODS, stageIndexFor, STAGES, type FoodId, type Reaction } from "../game/content";
import {
  ball,
  BED_POS,
  constrain,
  controls,
  cowEvents,
  drag,
  env,
  forward,
  pet,
  pointer,
  rand,
  ROAM_RADIUS,
  view,
} from "../game/runtime";
import { needOf, useGame } from "../game/store";
import { sfx } from "../game/audio";
import { CONFETTI, emit, HEARTS } from "./fx";
import { heartGeometry, radialTexture } from "./shapes";
import { PetBubble, type Emote } from "../ui/PetBubble";

const damp = MathUtils.damp;
const clamp01 = (v: number) => Math.max(0, Math.min(1, v));
const easeInOut = (x: number) => (x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2);
const easeOutBack = (x: number) => {
  const c1 = 1.7;
  return 1 + (c1 + 1) * Math.pow(x - 1, 3) + c1 * Math.pow(x - 1, 2);
};
const wrap = (a: number) => {
  while (a > Math.PI) a -= Math.PI * 2;
  while (a < -Math.PI) a += Math.PI * 2;
  return a;
};

type ActKind =
  | "eat"
  | "love"
  | "yum"
  | "treat"
  | "spicy"
  | "bleh"
  | "refuse"
  | "boop"
