const mkAct = (kind: ActKind, extra: Partial<Act> = {}): Act => ({
  kind,
  t: 0,
  dur: DUR[kind],
  flags: new Set(),
  last: 0,
  ...extra,
});

const once = (a: Act, key: string) => {
  if (a.flags.has(key)) return false;
  a.flags.add(key);
  return true;
};

