        f.state = "falling";
        const away = tmpB.copy(f.from).sub(pet.mouth).setY(0).normalize();
        f.vel.set(away.x * 1.3 + rand(-0.5, 0.5), 2.6, away.z * 1.3 + rand(-0.5, 0.5));
