      }
    } else if (f.state === "falling") {
      f.vel.y -= 9.8 * dt;
      f.pos.addScaledVector(f.vel, dt);
      const onIsland = Math.hypot(f.pos.x, f.pos.z) < ISLAND_RADIUS - 0.15;
      const floor = 0.1;
      if (onIsland && f.pos.y <= floor && f.vel.y < 0) {
        f.pos.y = floor;
        if (Math.abs(f.vel.y) > 1.2 && f.bounces < 3) {
          f.vel.y *= -0.38;
          f.vel.x *= 0.6;
