        lastRefuse.current = t;
        cowEvents.emit({ type: "refuse", reason: check });
      }
    }
  });

  if (!food) return null;
  return (
    <group ref={ref} renderOrder={20}>
      <FoodModel id={food} overlay />
    </group>
  );
}

