import { useEffect, useRef, type ComponentRef } from "react";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { OrbitControls } from "@react-three/drei";
import { NeutralToneMapping, Plane, Raycaster, Vector2, Vector3 } from "three";
import { controls, pet, pointer, view } from "../game/runtime";
import { useGame } from "../game/store";
import { SkyAndLights } from "./Sky";
import { Island } from "./Island";
import { Cow } from "./Cow";
import { Egg } from "./Egg";
import { Ball, DraggedFood, FloatingTexts, Poops, WorldFoods } from "./Interactables";
import { Effects } from "./Effects";

const TARGET = new Vector3(0, 0.55, 0);

function CameraRig() {
  const ref = useRef<ComponentRef<typeof OrbitControls>>(null);
  const camera = useThree((s) => s.camera);
  const width = useThree((s) => s.size.width);
  const height = useThree((s) => s.size.height);
  const mode = useGame((s) => s.mode);

  useEffect(() => {
    controls.enabled = (v) => {
      if (ref.current) ref.current.enabled = v && useGame.getState().mode !== "clean";
    };
  }, []);

  useEffect(() => {
    if (ref.current) ref.current.enabled = mode !== "clean";
  }, [mode]);

  useEffect(() => {
    const aspect = width / height;
    const dist = aspect < 0.62 ? 18.5 : aspect < 0.85 ? 16 : aspect < 1.2 ? 13 : aspect < 1.6 ? 11.2 : 10.4;
    const target = TARGET.clone();
    if (aspect < 0.85) target.y = 0.2;
    const dir = new Vector3(0, 0.4, 1).normalize();
    camera.position.copy(dir.multiplyScalar(dist).add(target));
    if (ref.current) {
      ref.current.target.copy(target);
      ref.current.update();
    }
  }, [width, height, camera]);

  return (
    <OrbitControls
      ref={ref}
      target={TARGET}
      enablePan={false}
      enableDamping
      dampingFactor={0.08}
      minDistance={6.5}
      maxDistance={21}
      minPolarAngle={0.55}
      maxPolarAngle={1.36}
      minAzimuthAngle={-1.15}
      maxAzimuthAngle={1.15}
      rotateSpeed={0.55}
      zoomSpeed={0.7}
    />
  );
}

