      onClick={() => {
        initAudio();
        sfx.click();
        onClick();
      }}
      disabled={disabled}
      title={kbd ? `${label} (${kbd})` : label}
    >
      <span className="dock-icon">{icon}</span>
      <span className="dock-label">{label}</span>
