  happy: { label: "Joy", color: "#ff7eb3", low: "is bored" },
  energy: { label: "Energy", color: "#7aa8ff", low: "is sleepy" },
  hygiene: { label: "Hygiene", color: "#5fd0c9", low: "needs a bath" },
