+}
+
+@keyframes throb {
+  0%,
+  100% {
+    transform: scale(1);
+  }
+  50% {
+    transform: scale(1.14);
+  }
+}
+@keyframes stripes {
+  to {
+    background-position: 17px 0;
+  }
+}
+
+.poop-nudge {
+  display: inline-flex;
+  align-items: center;
+  gap: 5px;
+  padding: 6px 12px;
+  border-radius: 999px;
+  background: #fff4e6;
+  color: #8a5a36;
+  font-weight: 700;
+  font-size: 13px;
