+}
+.dock-btn:hover:not(:disabled) {
+  background: color-mix(in srgb, var(--c) 12%, transparent);
+  transform: translateY(-3px);
+}
+.dock-btn:active:not(:disabled) {
+  transform: scale(0.93);
+}
+.dock-btn:disabled {
+  opacity: 0.38;
+  cursor: not-allowed;
+}
+
+.dock-icon {
+  width: 46px;
+  height: 46px;
+  border-radius: 16px;
+  display: grid;
+  place-items: center;
+  color: #fff;
+  background: linear-gradient(160deg, color-mix(in srgb, var(--c) 78%, white), var(--c));
+  box-shadow:
+    0 6px 14px -6px var(--c),
+    inset 0 -3px 0 rgba(0, 0, 0, 0.1);
+}
+
+.dock-label {
+  font-size: 13px;
+  font-weight: 600;
+}
+
+.dock-btn.is-active {
+  background: color-mix(in srgb, var(--c) 18%, white);
+}
+.dock-btn.is-active .dock-icon {
+  transform: translateY(-2px) rotate(-6deg);
+}
+.dock-btn.is-pulse .dock-icon {
+  animation: throb 0.9s ease-in-out infinite;
+}
+
+.dock-badge {
+  position: absolute;
+  top: 3px;
+  right: 10px;
+  min-width: 20px;
+  height: 20px;
+  padding: 0 5px;
+  border-radius: 99px;
+  background: #8a5a36;
+  color: white;
+  font-size: 12px;
+  font-weight: 700;
+  display: grid;
+  place-items: center;
+  border: 2px solid white;
+  animation: pop-in 0.35s cubic-bezier(0.3, 1.6, 0.5, 1);
+}
+
+/* ---------- Panels ---------- */
+
+.panel {
+  width: min(760px, 100%);
+  padding: 12px 14px 14px;
+  animation: slide-up 0.32s cubic-bezier(0.2, 1.2, 0.4, 1);
+}
+
+@keyframes slide-up {
+  from {
+    opacity: 0;
+    transform: translateY(18px) scale(0.98);
+  }
+}
+
+.panel-head {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  margin-bottom: 10px;
+}
+.panel-head .icon-btn {
+  width: 32px;
+  height: 32px;
+  border-radius: 11px;
+  box-shadow: none;
+  margin-left: auto;
+  flex: none;
+}
+
+.panel-title {
+  font-size: 17px;
+  font-weight: 700;
+  white-space: nowrap;
+}
+
+.panel-hint {
+  font-size: 13px;
+  color: var(--ink-soft);
+  overflow: hidden;
+  text-overflow: ellipsis;
+  white-space: nowrap;
+}
+
+.food-row {
+  display: flex;
+  gap: 8px;
+  overflow-x: auto;
+  padding: 4px 2px 4px;
+  scrollbar-width: none;
+  touch-action: pan-x;
+}
+.food-row::-webkit-scrollbar {
+  display: none;
+}
+
+.food-card {
+  position: relative;
+  flex: none;
+  width: 92px;
+  padding: 10px 6px 8px;
+  border-radius: 18px;
+  background: var(--card-strong);
+  box-shadow:
+    0 4px 10px -6px rgba(60, 40, 90, 0.35),
+    inset 0 0 0 1.5px rgba(58, 46, 77, 0.06);
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 3px;
+  touch-action: pan-x;
+  transition:
+    transform 0.18s cubic-bezier(0.3, 1.6, 0.5, 1),
+    box-shadow 0.2s ease,
+    opacity 0.2s ease;
+}
+.food-card:hover:not(.is-locked) {
+  transform: translateY(-4px) rotate(-1.5deg);
+  box-shadow:
+    0 10px 18px -8px rgba(60, 40, 90, 0.4),
+    inset 0 0 0 2px rgba(255, 111, 163, 0.35);
+}
+.food-card:active:not(.is-locked) {
+  transform: scale(0.95);
+}
+.food-card.is-lifted {
+  opacity: 0.35;
+  transform: scale(0.92);
+}
+
+.food-icon {
+  width: 48px;
+  height: 48px;
+  display: grid;
+  place-items: center;
+  filter: drop-shadow(0 3px 3px rgba(60, 40, 90, 0.18));
+  pointer-events: none;
+}
+
+.food-name {
+  font-size: 13px;
+  font-weight: 600;
+  line-height: 1.1;
+  text-align: center;
+  white-space: nowrap;
+}
+
+.food-chips {
+  display: flex;
+  gap: 4px;
+  font-size: 11px;
+  font-weight: 700;
+  min-height: 15px;
+}
+.food-chip {
+  display: inline-flex;
+  align-items: center;
+  gap: 1px;
+}
+
+.food-fav {
+  position: absolute;
+  top: 6px;
+  right: 7px;
+  color: var(--pink);
+  animation: throb 1.6s ease-in-out infinite;
+}
+
+.food-card.is-locked {
+  cursor: default;
+}
+.food-card.is-locked .food-icon,
+.food-card.is-locked .food-name,
+.food-card.is-locked .food-chips,
+.food-card.is-locked .acc-slot {
+  filter: grayscale(1) opacity(0.35);
+}
+
+.food-lock {
+  position: absolute;
+  inset: 0;
+  border-radius: inherit;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  justify-content: center;
+  gap: 3px;
+  font-size: 12px;
+  font-weight: 700;
+  color: #6b5a80;
+}
+
+.food-cooldown {
+  position: absolute;
+  inset: 0;
+  border-radius: inherit;
+  display: grid;
+  place-items: center;
+  background: conic-gradient(rgba(58, 46, 77, 0.45) var(--p), rgba(58, 46, 77, 0.12) 0);
+  color: white;
+  font-weight: 700;
+  font-size: 16px;
+  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.35);
+}
+
+.acc-card.is-on {
+  box-shadow:
+    0 6px 14px -8px rgba(107, 79, 196, 0.6),
+    inset 0 0 0 2.5px #a98bff;
