+
+/* ---------- Toasts ---------- */
+
+.toasts {
+  position: fixed;
+  top: max(18px, env(safe-area-inset-top));
+  left: 50%;
+  transform: translateX(-50%);
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 6px;
+  pointer-events: none;
+  z-index: 30;
+  width: min(420px, calc(100% - 32px));
+}
+
+.toast {
+  padding: 9px 16px;
+  border-radius: 999px;
+  background: var(--card-strong);
+  box-shadow: var(--shadow);
+  font-weight: 600;
+  font-size: 14px;
+  text-align: center;
+  animation: toast-in 0.4s cubic-bezier(0.3, 1.6, 0.5, 1);
+  backdrop-filter: blur(12px);
+  -webkit-backdrop-filter: blur(12px);
+}
+.toast--good {
+  background: #eafff0;
+  color: #2c7a45;
+}
+.toast--warn {
+  background: #fff1e6;
+  color: #b4521f;
+}
+.toast--level {
+  background: linear-gradient(135deg, #fff6d6, #ffe6f1);
+  color: #9a5a00;
+}
+
+@keyframes toast-in {
+  from {
+    opacity: 0;
+    transform: translateY(-14px) scale(0.9);
+  }
+}
+
+@keyframes pop-in {
+  from {
+    transform: scale(0.3);
+    opacity: 0;
+  }
+}
+
+/* ---------- 3D-anchored bubbles ---------- */
+
+.pet-bubble {
+  position: relative;
+  transform-origin: 50% 100%;
+  animation: bubble-in 0.35s cubic-bezier(0.3, 1.7, 0.5, 1);
+  white-space: nowrap;
+  font-family: "Fredoka Variable", "Fredoka", system-ui, sans-serif;
+  pointer-events: none;
+}
+
+.pet-bubble::after {
+  content: "";
+  position: absolute;
+  left: 50%;
+  bottom: -7px;
+  width: 14px;
+  height: 14px;
+  background: #fff;
+  transform: translateX(-50%) rotate(45deg);
+  border-radius: 3px;
+  z-index: -1;
+}
+
+.pet-bubble--icon,
+.pet-bubble--need {
+  width: 46px;
+  height: 46px;
+  border-radius: 50%;
+  background: #fff;
+  display: grid;
+  place-items: center;
+  box-shadow: 0 8px 18px -8px rgba(60, 40, 90, 0.45);
+}
+
+.pet-bubble--need {
+  animation:
+    bubble-in 0.35s cubic-bezier(0.3, 1.7, 0.5, 1),
+    bob 1.6s ease-in-out 0.35s infinite;
+}
+
+.pet-bubble--text {
+  padding: 7px 14px;
+  border-radius: 999px;
+  background: #fff;
+  color: var(--ink);
+  font-weight: 700;
+  font-size: 17px;
+  box-shadow: 0 8px 18px -8px rgba(60, 40, 90, 0.45);
+}
+
+@keyframes bubble-in {
+  from {
+    transform: scale(0.2) translateY(10px);
+    opacity: 0;
+  }
+}
+
+@keyframes bob {
+  0%,
+  100% {
+    transform: translateY(0);
+  }
+  50% {
+    transform: translateY(-5px);
+  }
+}
+
+.float-text {
+  font-family: "Fredoka Variable", "Fredoka", system-ui, sans-serif;
+  font-weight: 700;
+  font-size: 18px;
+  white-space: nowrap;
+  pointer-events: none;
+  text-shadow:
+    0 0 3px #fff,
+    0 0 3px #fff,
+    0 2px 0 #fff,
+    0 0 10px rgba(255, 255, 255, 0.9);
+  animation: float-up 1.5s cubic-bezier(0.2, 0.8, 0.3, 1) forwards;
+}
+
+@keyframes float-up {
+  0% {
+    transform: translateY(8px) scale(0.5);
+    opacity: 0;
+  }
+  15% {
+    transform: translateY(0) scale(1.15);
+    opacity: 1;
+  }
+  30% {
+    transform: translateY(-6px) scale(1);
+  }
+  100% {
+    transform: translateY(-58px) scale(0.95);
+    opacity: 0;
+  }
+}
+
+/* ---------- Egg ---------- */
+
+.egg-hint {
