+  padding: 10px 14px;
+  border-radius: 16px;
+  border: 2px solid #ffd0e2;
+  background: #fff;
+  outline: none;
+}
+.name-input:focus {
+  border-color: var(--pink);
+}
+.name-ideas {
+  display: flex;
+  flex-wrap: wrap;
+  justify-content: center;
+  gap: 6px;
+  margin: 12px 0 16px;
+}
+
+.levelup {
+  position: fixed;
+  left: 50%;
+  top: 22%;
+  transform: translateX(-50%);
+  z-index: 35;
+  width: min(340px, calc(100% - 32px));
+  padding: 20px 20px 18px;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 8px;
+  text-align: center;
+  background: linear-gradient(160deg, rgba(255, 250, 230, 0.95), rgba(255, 234, 244, 0.95));
+  animation: levelup-in 0.6s cubic-bezier(0.3, 1.5, 0.5, 1);
+}
+@keyframes levelup-in {
+  from {
+    opacity: 0;
+    transform: translateX(-50%) scale(0.5) rotate(-6deg);
+  }
+}
+.levelup-star {
+  width: 58px;
+  height: 58px;
+  border-radius: 50%;
+  display: grid;
+  place-items: center;
+  color: #fff;
+  background: linear-gradient(160deg, #ffd35c, #ffab2e);
+  box-shadow: 0 8px 20px -8px #ffab2e;
+  margin-top: -46px;
+  animation: spin-slow 6s linear infinite;
+}
+@keyframes spin-slow {
+  to {
+    transform: rotate(360deg);
+  }
+}
+.levelup-title {
+  font-size: 28px;
+  font-weight: 700;
+  color: #9a5a00;
+}
+.levelup-stage {
+  font-weight: 600;
+}
+.levelup-unlocks {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 6px;
+  justify-content: center;
+  align-items: center;
+  font-size: 13px;
+}
+
+.settings {
+  position: fixed;
+  top: calc(max(16px, env(safe-area-inset-top)) + 50px);
+  right: max(18px, env(safe-area-inset-right));
+  z-index: 25;
+  width: min(300px, calc(100% - 36px));
+  padding: 14px;
+  background: var(--card-strong);
+  animation: slide-up 0.3s cubic-bezier(0.2, 1.2, 0.4, 1);
+}
+.journal {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 6px;
+  margin-bottom: 12px;
+}
+.journal div {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  padding: 8px 2px;
+  border-radius: 14px;
+  background: #f7f3ff;
+}
+.journal b {
+  font-size: 20px;
+}
+.journal span {
+  font-size: 11px;
+  color: var(--ink-soft);
+  text-align: center;
+}
+.shortcuts {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 6px 10px;
+  margin-bottom: 12px;
+  font-size: 12px;
+  color: var(--ink-soft);
+}
+kbd {
+  font-family: inherit;
+  font-weight: 700;
+  font-size: 11px;
+  padding: 1px 6px;
+  border-radius: 6px;
+  background: #fff;
+  box-shadow: inset 0 -2px 0 rgba(58, 46, 77, 0.12), 0 0 0 1px rgba(58, 46, 77, 0.1);
+  color: var(--ink);
+}
+
+/* ---------- Night / asleep ---------- */
+
+.hud.is-asleep .card,
+.hud.is-asleep .panel,
+.hud.is-asleep .dock,
+.hud.is-asleep .icon-btn {
+  background: rgba(34, 32, 70, 0.62);
+  border-color: rgba(160, 160, 255, 0.18);
+  color: #e9e6ff;
+}
+.hud.is-asleep .muted,
+.hud.is-asleep .mood,
+.hud.is-asleep .panel-hint,
+.hud.is-asleep .stat-val {
+  color: #b3add6;
+}
+.hud.is-asleep .bar,
+.hud.is-asleep .xp {
+  background: rgba(255, 255, 255, 0.12);
+}
+.hud.is-asleep .avatar {
+  background: radial-gradient(circle at 35% 30%, #5a5892, #34325f 70%);
+}
+.hud.is-asleep .chip:not(.chip--level):not(.chip--stage) {
+  background: rgba(255, 255, 255, 0.12);
+}
+
+/* ---------- Responsive ---------- */
+
+@media (max-width: 760px) {
+  .hud {
+    padding: max(10px, env(safe-area-inset-top)) max(10px, env(safe-area-inset-right)) max(10px, env(safe-area-inset-bottom))
+      max(10px, env(safe-area-inset-left));
+  }
+  .hud-top {
+    flex-direction: column;
+    align-items: stretch;
+    gap: 8px;
+  }
+  .hud-left {
+    gap: 8px;
+  }
+  .brand {
+    font-size: 20px;
+    padding-right: 140px;
+  }
+  .hud-right {
+    align-items: stretch;
+  }
+  .utility {
+    position: absolute;
+    top: max(10px, env(safe-area-inset-top));
+    right: max(10px, env(safe-area-inset-right));
+    gap: 6px;
+  }
+  .utility .icon-btn {
+    width: 36px;
+    height: 36px;
+    border-radius: 12px;
+  }
+  .pet-card {
+    width: 100%;
+    padding: 8px 12px 8px 8px;
+    gap: 10px;
+  }
+  .avatar {
+    width: 48px;
+    height: 48px;
+    border-radius: 16px;
+  }
+  .avatar svg {
+    width: 36px;
+    height: 36px;
+  }
+  .pet-name {
+    font-size: 18px;
+  }
+  .mood {
+    display: none;
+  }
+  .stats-card {
+    width: 100%;
+    flex-direction: row;
+    gap: 8px;
+    padding: 8px 10px;
+  }
+  .stat {
+    flex: 1;
+    flex-direction: column;
+    gap: 4px;
+  }
+  .stat-body {
+    width: 100%;
+  }
+  .stat-label span:first-child {
+    display: none;
+  }
+  .stat-label {
+    justify-content: center;
+    margin-bottom: 2px;
+    font-size: 11px;
+  }
+  .stat-icon {
+    width: 24px;
+    height: 24px;
+    border-radius: 8px;
+  }
+  .bar {
+    height: 6px;
+  }
+  .poop-nudge {
+    align-self: flex-end;
+  }
+  .dock {
+    gap: 2px;
+    padding: 6px;
+    border-radius: 24px;
+    width: 100%;
+    justify-content: space-between;
+  }
+  .dock-btn {
+    width: auto;
+    flex: 1;
+    padding: 6px 2px;
+  }
+  .dock-icon {
+    width: 40px;
+    height: 40px;
+    border-radius: 14px;
+  }
+  .dock-icon svg {
+    width: 22px;
+    height: 22px;
+  }
+  .dock-label {
+    font-size: 11.5px;
+  }
+  .dock-badge {
+    right: 4px;
+  }
+  .panel-hint {
+    display: none;
+  }
+  .mode-copy .panel-hint {
+    display: block;
+    font-size: 12px;
+  }
+  .mode-bar {
+    gap: 10px;
+    padding: 10px 12px;
+  }
+  .mode-meter {
+    width: 96px;
+  }
+  .food-card {
+    width: 82px;
+  }
+  .settings {
+    top: calc(max(10px, env(safe-area-inset-top)) + 46px);
+    right: max(10px, env(safe-area-inset-right));
+  }
+}
+
+@media (max-height: 560px) and (min-width: 761px) {
+  .stats-card {
+    gap: 4px;
+    padding: 8px 12px;
+  }
+  .pet-card .mood {
+    display: none;
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
