const INTERRUPTIBLE: Partial<Record<ActKind, boolean>> = {
  look: true,
  sniff: true,
  hop: true,
  spin: true,
  moo: true,
  giggle: true,
  boop: true,
  shiver: true,
  sadmoo: true,
};

interface Act {
  kind: ActKind;
  t: number;
  dur: number;
  food?: FoodId;
  ground?: boolean;
  flags: Set<string>;
  last: number;
}

interface Expr {
  eyes: "open" | "happy" | "closed" | "squint";
  lid: number;
  mouth: "smile" | "frown" | "flat";
  open: number;
  tongue: boolean;
  brows: "none" | "sad" | "angry" | "raised";
  blush: number;
  earDroop: number;
  tail: number;
  cheekPuff: number;
  red: number;
}

interface Pose {
  hop: number;
  squash: number;
  roll: number;
  lie: number;
  headDown: number;
  spin: number;
  lunge: number;
  yaw: number;
  pitch: number;
  headRoll: number;
}

const mkAct = (kind: ActKind, extra: Partial<Act> = {}): Act => ({
  kind,
  t: 0,
  dur: DUR[kind],
  flags: new Set(),
  last: 0,
  ...extra,
});

const once = (a: Act, key: string) => {
  if (a.flags.has(key)) return false;
  a.flags.add(key);
  return true;
};

const V = () => new Vector3();
const tmpA = V();
const tmpB = V();
const tmpC = V();
const Z = new Vector3(0, 0, 1);

function Patch({
  dir,
  size,
  material,
  depth = 0.895,
  groupRef,
}: {
  dir: [number, number, number];
  size: [number, number];
  material: Material;
  depth?: number;
  groupRef?: (o: Object3D | null) => void;
}) {
  const { pos, quat } = useMemo(() => {
    const n = new Vector3(...dir).normalize();
    return { pos: n.clone().multiplyScalar(depth), quat: new Quaternion().setFromUnitVectors(Z, n) };
  }, [dir, depth]);
  return (
    <group ref={groupRef} position={pos} quaternion={quat}>
      <mesh scale={[size[0], size[1], 0.12]} material={material}>
        <sphereGeometry args={[1, 24, 16]} />
      </mesh>
    </group>
  );
}

