const URL = process.env.URL ?? "http://127.0.0.1:9359/";
const OUT = new globalThis.URL("../.tmp/shots/", import.meta.url).pathname;
mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch({
  args: ["--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"],
});
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const page = await context.newPage();
const problems = [];
page.on("console", (m) => {
  if (m.type() === "error" || m.type() === "warning") problems.push(`[${m.type()}] ${m.text()}`);
});
page.on("pageerror", (e) => problems.push(`[pageerror] ${e.message}`));

const sleep = (ms) => page.waitForTimeout(ms);
const shot = (name) => page.screenshot({ path: `${OUT}${name}.png` });
const state = () =>
  page.evaluate(async () => {
    const { useGame } = await import("/src/game/store.ts");
    const s = useGame.getState();
    return {
      hatched: s.hatched,
      naming: s.naming,
      stats: s.stats,
      xp: s.xp,
      level: s.level,
      fed: s.totals.fed,
      pets: s.totals.pets,
      mode: s.mode,
      panel: s.panel,
      asleep: s.asleep,
      foods: s.foods.length,
      toasts: s.toasts.map((t) => t.text),
    };
  });
const screenOf = (which, dy = 0) =>
  page.evaluate(
    async ([which, dy]) => {
      const rt = await import("/src/game/runtime.ts");
      const v = rt.pet[which].clone();
      v.y += dy;
      v.project(rt.view.camera);
      const r = rt.view.canvas.getBoundingClientRect();
      return { x: r.left + ((v.x + 1) / 2) * r.width, y: r.top + ((1 - v.y) / 2) * r.height };
    },
    [which, dy],
  );

