await page.keyboard.press("s");
await sleep(3000);
await shot("16-sleep");
console.log("asleep:", (await state()).asleep);
await page.keyboard.press("s");
await sleep(1500);

await page.setViewportSize({ width: 390, height: 844 });
await sleep(1500);
