  const poops = useGame((s) => s.poops);
  return (
    <>
      {poops.map((p) => (
        <PoopItem key={p.id} p={p} />
      ))}
    </>
  );
}

export function FloatingTexts() {
  const floats = useGame((s) => s.floats);
  return (
    <>
      {floats.map((f) => (
        <group key={f.id} position={f.pos}>
          <Html center zIndexRange={[6, 0]} style={{ pointerEvents: "none" }}>
            <div className="float-text" style={{ color: f.color }}>
              {f.text}
            </div>
          </Html>
        </group>
      ))}
    </>
  );
}

