      if (speed > 0.01 && ball.pos.y <= r + 0.01) {
        axis.set(ball.vel.z, 0, -ball.vel.x).normalize();
        q.setFromAxisAngle(axis, (speed * dt) / r);
        m.quaternion.premultiply(q);
