    const pop = k < 1 ? 1 + Math.sin(k * Math.PI) * 0.35 : 1;
    ref.current.scale.set(pop * Math.min(1, k * 2), Math.min(1, k * 2) * (1 + Math.sin(t * 3 + p.id) * 0.03), pop * Math.min(1, k * 2));
