success.beforeFullFileContent:
:root {
  --ink: #3a2e4d;
  --ink-soft: #7a6d8c;
  --card: rgba(255, 255, 255, 0.74);
  --card-strong: rgba(255, 255, 255, 0.9);
  --card-line: rgba(255, 255, 255, 0.95);
  --shadow: 0 10px 30px -12px rgba(60, 40, 90, 0.35), 0 2px 6px -2px rgba(60, 40, 90, 0.12);
  --radius: 22px;
  --pink: #ff6fa3;
  --gold: #ffb400;
  font-family: "Fredoka Variable", "Fredoka", ui-rounded, "SF Pro Rounded", system-ui, sans-serif;
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  margin: 0;
  height: 100%;
  overflow: hidden;
}

body {
  background: linear-gradient(#9fd6ff, #d9f0ff 60%, #fff3df);
  overscroll-behavior: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  border: 0;
  background: none;
  padding: 0;
}

button:focus-visible,
input:focus-visible {
  outline: 3px solid #8ec5ff;
  outline-offset: 2px;
}

.app {
  position: fixed;
  inset: 0;
}

.scene {
  position: absolute !important;
  inset: 0;
}

.scene canvas {
  touch-action: none;
  display: block;
}

body[data-hover="pet"] {
  cursor: grab;
}
body[data-hover="item"],
body[data-hover="poop"] {
  cursor: pointer;
}
body[data-mode="clean"],
body[data-mode="clean"][data-hover] {
  cursor:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='40' height='40' viewBox='0 0 40 40'><rect x='5' y='10' width='30' height='20' rx='7' fill='%23ffd84d' stroke='%23c99a00' stroke-width='2'/><rect x='5' y='22' width='30' height='8' rx='4' fill='%236fd3c9'/><circle cx='13' cy='16' r='2' fill='%23e6b800'/><circle cx='22' cy='14' r='1.5' fill='%23e6b800'/><circle cx='28' cy='18' r='2' fill='%23e6b800'/><circle cx='33' cy='7' r='4' fill='white' stroke='%2399e0ff' stroke-width='1.5'/></svg>")
      20 20,
    pointer;
}
body.is-dragging,
body.is-dragging * {
  cursor: grabbing !important;
}

/* ---------- HUD shell ---------- */

.hud {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: max(16px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right)) max(14px, env(safe-area-inset-bottom))
    max(18px, env(safe-area-inset-left));
}

.hud-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}

.hud-left,
.hud-right {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.hud-right {
  align-items: flex-end;
}

.card,
.panel,
.dock,
.icon-btn,
.btn,
.poop-nudge,
.toast,
.modal-backdrop {
  pointer-events: auto;
}

.card,
.panel {
  background: var(--card);
  border: 1.5px solid var(--card-line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  backdrop-filter: blur(14px) saturate(1.3);
  -webkit-backdrop-filter: blur(14px) saturate(1.3);
  transition:
    background 0.8s ease,
    color 0.8s ease,
    border-color 0.8s ease;
}

.brand {
  margin: 0;
  font-size: 26px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: #fff;
  text-shadow:
    0 2px 0 rgba(90, 60, 140, 0.25),
    0 6px 20px rgba(90, 60, 140, 0.25);
  padding: 4px 4px 2px;
  pointer-events: none;
}

.muted {
  color: var(--ink-soft);
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  background: rgba(255, 255, 255, 0.85);
  box-shadow: inset 0 0 0 1.5px rgba(58, 46, 77, 0.08);
}
.chip--level {
  background: linear-gradient(135deg, #ffd35c, #ffb13b);
  color: #6b4200;
  box-shadow: none;
}
.chip--stage {
  background: #efe6ff;
  color: #6b4fc4;
  box-shadow: none;
}
.chip--btn {
  cursor: pointer;
  transition: transform 0.15s ease;
}
.chip--btn:hover {
  transform: translateY(-1px);
}
.chip--btn.is-on {
  background: var(--pink);
  color: white;
  box-shadow: none;
}

/* ---------- Pet card ---------- */

.pet-card {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 12px 16px 12px 12px;
  width: 300px;
}

.avatar {
  width: 64px;
  height: 64px;
  border-radius: 20px;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 35% 30%, #fff, #ffe3ef 70%);
  box-shadow: inset 0 0 0 2px rgba(255, 111, 163, 0.18);
  flex: none;
}

.pet-meta {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.pet-name-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.pet-name {
  font-size: 21px;
  font-weight: 700;
  line-height: 1.05;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pet-sub {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
}

.xp {
  height: 7px;
  border-radius: 99px;
  background: rgba(58, 46, 77, 0.1);
  overflow: hidden;
}
.xp-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ffd35c, #ff9fce);
  transition: width 0.6s cubic-bezier(0.2, 0.9, 0.3, 1.2);
}

.mood {
  font-size: 13px;
  color: var(--ink-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ---------- Stats ---------- */

.utility {
  display: flex;
  gap: 8px;
}

.icon-btn {
  width: 40px;
  height: 40px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: var(--card);
  border: 1.5px solid var(--card-line);
  box-shadow: var(--shadow);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  transition:
    transform 0.15s ease,
    background 0.3s ease;
}
.icon-btn:hover {
  transform: translateY(-1px);
  background: var(--card-strong);
}
.icon-btn:active {
  transform: scale(0.94);
}
.icon-btn.is-off {
  color: var(--ink-soft);
  opacity: 0.8;
}
.icon-btn.is-active {
  background: #fff;
  color: #6b4fc4;
}
.icon-btn.tiny {
  width: 24px;
  height: 24px;
  border-radius: 8px;
  box-shadow: none;
  background: rgba(255, 255, 255, 0.6);
  border: 0;
  color: var(--ink-soft);
}

.stats-card {
  width: 236px;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.stat {
  display: flex;
  align-items: center;
  gap: 10px;
}

.stat-icon {
  width: 28px;
  height: 28px;
  flex: none;
  border-radius: 10px;
  display: grid;
  place-items: center;
  color: #fff;
  background: var(--c);
  box-shadow: 0 3px 8px -3px var(--c);
}

.stat-body {
  flex: 1;
  min-width: 0;
}

.stat-label {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  font-weight: 600;
  margin-bottom: 3px;
}

.stat-val {
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}

.bar {
  height: 8px;
  border-radius: 99px;
  background: rgba(58, 46, 77, 0.1);
  overflow: hidden;
}
.bar-fill {
  height: 100%;
  border-radius: inherit;
  background: var(--c);
  transition: width 0.5s ease;
}

.stat.is-low .stat-icon {
  animation: throb 1s ease-in-out infinite;
}
.stat.is-low .bar-fill {
  background: repeating-linear-gradient(-45deg, var(--c) 0 6px, color-mix(in srgb, var(--c) 70%, white) 6px 12px);
  background-size: 17px 17px;
  animation: stripes 0.8s linear infinite;
}
.stat.is-low .stat-val {
  color: #e2536f;
}

@keyframes throb {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.14);
  }
}
@keyframes stripes {
  to {
    background-position: 17px 0;
  }
}

.poop-nudge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 12px;
  border-radius: 999px;
  background: #fff4e6;
  color: #8a5a36;
  font-weight: 700;
  font-size: 13px;
  box-shadow: var(--shadow);
  animation: wiggle 2.4s ease-in-out infinite;
}

@keyframes wiggle {
  0%,
  86%,
  100% {
    transform: rotate(0);
  }
  90% {
    transform: rotate(-8deg);
  }
  95% {
    transform: rotate(8deg);
  }
}

/* ---------- Bottom ---------- */

.hud-bottom {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  pointer-events: none;
}

.panel-slot {
  width: 100%;
  display: flex;
  justify-content: center;
  pointer-events: none;
}

.dock {
  display: flex;
  gap: 6px;
  padding: 8px;
  border-radius: 28px;
  background: var(--card);
  border: 1.5px solid var(--card-line);
  box-shadow: var(--shadow);
  backdrop-filter: blur(14px) saturate(1.3);
  -webkit-backdrop-filter: blur(14px) saturate(1.3);
  transition: background 0.8s ease;
}

.dock-btn {
  position: relative;
  width: 76px;
  padding: 8px 4px 7px;
  border-radius: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  transition:
    transform 0.18s cubic-bezier(0.3, 1.6, 0.5, 1),
    background 0.2s ease;
}
.dock-btn:hover:not(:disabled) {
  background: color-mix(in srgb, var(--c) 12%, transparent);
  transform: translateY(-3px);
}
.dock-btn:active:not(:disabled) {
  transform: scale(0.93);
}
.dock-btn:disabled {
  opacity: 0.38;
  cursor: not-allowed;
}

.dock-icon {
  width: 46px;
  height: 46px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  color: #fff;
  background: linear-gradient(160deg, color-mix(in srgb, var(--c) 78%, white), var(--c));
  box-shadow:
    0 6px 14px -6px var(--c),
    inset 0 -3px 0 rgba(0, 0, 0, 0.1);
}

.dock-label {
  font-size: 13px;
  font-weight: 600;
}

.dock-btn.is-active {
  background: color-mix(in srgb, var(--c) 18%, white);
}
.dock-btn.is-active .dock-icon {
  transform: translateY(-2px) rotate(-6deg);
}
.dock-btn.is-pulse .dock-icon {
  animation: throb 0.9s ease-in-out infinite;
}

.dock-badge {
  position: absolute;
  top: 3px;
  right: 10px;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: 99px;
  background: #8a5a36;
  color: white;
  font-size: 12px;
  font-weight: 700;
  display: grid;
  place-items: center;
  border: 2px solid white;
  animation: pop-in 0.35s cubic-bezier(0.3, 1.6, 0.5, 1);
}

/* ---------- Panels ---------- */

.panel {
  width: min(760px, 100%);
  padding: 12px 14px 14px;
  animation: slide-up 0.32s cubic-bezier(0.2, 1.2, 0.4, 1);
}

@keyframes slide-up {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.98);
  }
}

.panel-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}
.panel-head .icon-btn {
  width: 32px;
  height: 32px;
  border-radius: 11px;
  box-shadow: none;
  margin-left: auto;
  flex: none;
}

.panel-title {
  font-size: 17px;
  font-weight: 700;
  white-space: nowrap;
}

.panel-hint {
  font-size: 13px;
  color: var(--ink-soft);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.food-row {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding: 4px 2px 4px;
  scrollbar-width: none;
  touch-action: pan-x;
}
.food-row::-webkit-scrollbar {
  display: none;
}

.food-card {
  position: relative;
  flex: none;
  width: 92px;
  padding: 10px 6px 8px;
  border-radius: 18px;
  background: var(--card-strong);
  box-shadow:
    0 4px 10px -6px rgba(60, 40, 90, 0.35),
    inset 0 0 0 1.5px rgba(58, 46, 77, 0.06);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  touch-action: pan-x;
  transition:
    transform 0.18s cubic-bezier(0.3, 1.6, 0.5, 1),
    box-shadow 0.2s ease,
    opacity 0.2s ease;
}
.food-card:hover:not(.is-locked) {
  transform: translateY(-4px) rotate(-1.5deg);
  box-shadow:
    0 10px 18px -8px rgba(60, 40, 90, 0.4),
    inset 0 0 0 2px rgba(255, 111, 163, 0.35);
}
.food-card:active:not(.is-locked) {
  transform: scale(0.95);
}
.food-card.is-lifted {
  opacity: 0.35;
  transform: scale(0.92);
}

.food-icon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  filter: drop-shadow(0 3px 3px rgba(60, 40, 90, 0.18));
  pointer-events: none;
}

.food-name {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.1;
  text-align: center;
  white-space: nowrap;
}

.food-chips {
  display: flex;
  gap: 4px;
  font-size: 11px;
  font-weight: 700;
  min-height: 15px;
}
.food-chip {
  display: inline-flex;
  align-items: center;
  gap: 1px;
}

.food-fav {
  position: absolute;
  top: 6px;
  right: 7px;
  color: var(--pink);
  animation: throb 1.6s ease-in-out infinite;
}

.food-card.is-locked {
  cursor: default;
}
.food-card.is-locked .food-icon,
.food-card.is-locked .food-name,
.food-card.is-locked .food-chips,
.food-card.is-locked .acc-slot {
  filter: grayscale(1) opacity(0.35);
}

.food-lock {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  font-size: 12px;
  font-weight: 700;
  color: #6b5a80;
}

.food-cooldown {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  display: grid;
  place-items: center;
  background: conic-gradient(rgba(58, 46, 77, 0.45) var(--p), rgba(58, 46, 77, 0.12) 0);
  color: white;
  font-weight: 700;
  font-size: 16px;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.35);
}

.acc-card.is-on {
  box-shadow:
    0 6px 14px -8px rgba(107, 79, 196, 0.6),
    inset 0 0 0 2.5px #a98bff;
  background: #f6f1ff;
}
.acc-slot {
  font-size: 11px;
  font-weight: 600;
  color: var(--ink-soft);
  text-transform: capitalize;
}
.acc-card.is-on .acc-slot {
  color: #6b4fc4;
}

.mode-bar {
  display: flex;
  align-items: center;
  gap: 16px;
  width: min(620px, 100%);
  padding: 12px 14px 12px 18px;
}

.mode-copy {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.mode-copy .panel-hint {
  white-space: normal;
}

.mode-meter {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 150px;
  font-weight: 700;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}
.mode-meter .bar {
  flex: 1;
  height: 10px;
}

.rally {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 70px;
}
.rally-num {
  font-size: 30px;
  font-weight: 700;
  line-height: 1;
  color: var(--pink);
  animation: pop-in 0.35s cubic-bezier(0.3, 1.8, 0.5, 1);
}
.rally-label {
  font-size: 12px;
  color: var(--ink-soft);
  white-space: nowrap;
}

.btn {
  padding: 10px 18px;
  border-radius: 14px;
  background: #fff;
  font-weight: 700;
  box-shadow:
    0 4px 10px -6px rgba(60, 40, 90, 0.4),
    inset 0 0 0 1.5px rgba(58, 46, 77, 0.08);
  transition: transform 0.15s cubic-bezier(0.3, 1.6, 0.5, 1);
  white-space: nowrap;
}
.btn:hover {
  transform: translateY(-2px);
}
.btn:active {
  transform: scale(0.96);
}
.btn.primary {
  background: linear-gradient(160deg, #ff8fbb, var(--pink));
  color: #fff;
  box-shadow:
    0 8px 16px -8px var(--pink),
    inset 0 -3px 0 rgba(0, 0, 0, 0.1);
}
.btn.danger {
  background: #fff0f2;
  color: #d23a5a;
}
.btn.danger.is-confirm {
  background: #e2536f;
  color: #fff;
}
.btn.wide {
  width: 100%;
}

/* ---------- Toasts ---------- */

.toasts {
  position: fixed;
  top: max(18px, env(safe-area-inset-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  pointer-events: none;
  z-index: 30;
  width: min(420px, calc(100% - 32px));
}

.toast {
  padding: 9px 16px;
  border-radius: 999px;
  background: var(--card-strong);
  box-shadow: var(--shadow);
  font-weight: 600;
  font-size: 14px;
  text-align: center;
  animation: toast-in 0.4s cubic-bezier(0.3, 1.6, 0.5, 1);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.toast--good {
  background: #eafff0;
  color: #2c7a45;
}
.toast--warn {
  background: #fff1e6;
  color: #b4521f;
}
.toast--level {
  background: linear-gradient(135deg, #fff6d6, #ffe6f1);
  color: #9a5a00;
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(-14px) scale(0.9);
  }
}

@keyframes pop-in {
  from {
    transform: scale(0.3);
    opacity: 0;
  }
}

/* ---------- 3D-anchored bubbles ---------- */

.pet-bubble {
  position: relative;
  transform-origin: 50% 100%;
  animation: bubble-in 0.35s cubic-bezier(0.3, 1.7, 0.5, 1);
  white-space: nowrap;
  font-family: "Fredoka Variable", "Fredoka", system-ui, sans-serif;
  pointer-events: none;
}

.pet-bubble::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -7px;
  width: 14px;
  height: 14px;
  background: #fff;
  transform: translateX(-50%) rotate(45deg);
  border-radius: 3px;
  z-index: -1;
}

.pet-bubble--icon,
.pet-bubble--need {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: #fff;
  display: grid;
  place-items: center;
  box-shadow: 0 8px 18px -8px rgba(60, 40, 90, 0.45);
}

.pet-bubble--need {
  animation:
    bubble-in 0.35s cubic-bezier(0.3, 1.7, 0.5, 1),
    bob 1.6s ease-in-out 0.35s infinite;
}

.pet-bubble--text {
  padding: 7px 14px;
  border-radius: 999px;
  background: #fff;
  color: var(--ink);
  font-weight: 700;
  font-size: 17px;
  box-shadow: 0 8px 18px -8px rgba(60, 40, 90, 0.45);
}

@keyframes bubble-in {
  from {
    transform: scale(0.2) translateY(10px);
    opacity: 0;
  }
}

@keyframes bob {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-5px);
  }
}

.float-text {
  font-family: "Fredoka Variable", "Fredoka", system-ui, sans-serif;
  font-weight: 700;
  font-size: 18px;
  white-space: nowrap;
  pointer-events: none;
  text-shadow:
    0 0 3px #fff,
    0 0 3px #fff,
    0 2px 0 #fff,
    0 0 10px rgba(255, 255, 255, 0.9);
  animation: float-up 1.5s cubic-bezier(0.2, 0.8, 0.3, 1) forwards;
}

@keyframes float-up {
  0% {
    transform: translateY(8px) scale(0.5);
    opacity: 0;
  }
  15% {
    transform: translateY(0) scale(1.15);
    opacity: 1;
  }
  30% {
    transform: translateY(-6px) scale(1);
  }
  100% {
    transform: translateY(-58px) scale(0.95);
    opacity: 0;
  }
}

/* ---------- Egg ---------- */

.egg-hint {
  position: fixed;
  left: 50%;
  bottom: max(28px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  padding: 14px 24px;
  text-align: center;
  animation: slide-up 0.5s cubic-bezier(0.2, 1.2, 0.4, 1);
}
.egg-hint-title {
  font-weight: 700;
  font-size: 18px;
}
.egg-hint-copy {
  color: var(--ink-soft);
  font-size: 14px;
  margin-top: 2px;
}
.egg-dots {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-top: 10px;
}
.egg-dots span {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: rgba(58, 46, 77, 0.14);
  transition:
    background 0.3s ease,
    transform 0.3s cubic-bezier(0.3, 1.8, 0.5, 1);
}
.egg-dots span.is-on {
  background: var(--gold);
  transform: scale(1.25);
}

/* ---------- Modal / level up / settings ---------- */

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(58, 46, 77, 0.28);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  animation: fade-in 0.25s ease;
}
@keyframes fade-in {
  from {
    opacity: 0;
  }
}

.modal {
  width: min(400px, 100%);
  padding: 24px 22px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  background: var(--card-strong);
  animation: pop-in 0.4s cubic-bezier(0.3, 1.5, 0.5, 1);
  user-select: text;
}
.modal-cow {
  width: 96px;
  height: 96px;
  border-radius: 32px;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 35% 30%, #fff, #ffe3ef 70%);
  margin-top: -64px;
  box-shadow: var(--shadow);
  animation: bob 2s ease-in-out infinite;
}
.modal-title {
  margin: 14px 0 4px;
  font-size: 22px;
}
.modal-copy {
  margin: 0 0 14px;
  color: var(--ink-soft);
}
.name-input {
  width: 100%;
  font: inherit;
  font-size: 22px;
  font-weight: 700;
  text-align: center;
  color: var(--ink);
  padding: 10px 14px;
  border-radius: 16px;
  border: 2px solid #ffd0e2;
  background: #fff;
  outline: none;
}
.name-input:focus {
  border-color: var(--pink);
}
.name-ideas {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  margin: 12px 0 16px;
}

.levelup {
  position: fixed;
  left: 50%;
  top: 22%;
  transform: translateX(-50%);
  z-index: 35;
  width: min(340px, calc(100% - 32px));
  padding: 20px 20px 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
  background: linear-gradient(160deg, rgba(255, 250, 230, 0.95), rgba(255, 234, 244, 0.95));
  animation: levelup-in 0.6s cubic-bezier(0.3, 1.5, 0.5, 1);
}
@keyframes levelup-in {
  from {
    opacity: 0;
    transform: translateX(-50%) scale(0.5) rotate(-6deg);
  }
}
.levelup-star {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  background: linear-gradient(160deg, #ffd35c, #ffab2e);
