/* ---------- HUD shell ---------- */

.hud {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: max(16px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right)) max(14px, env(safe-area-inset-bottom))
    max(18px, env(safe-area-inset-left));
}

.hud-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}

.hud-left,
.hud-right {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.hud-right {
  align-items: flex-end;
}

.card,
.panel,
.dock,
.icon-btn,
.btn,
.poop-nudge,
.toast,
.modal-backdrop {
  pointer-events: auto;
}

.card,
.panel {
  background: var(--card);
  border: 1.5px solid var(--card-line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  backdrop-filter: blur(14px) saturate(1.3);
  -webkit-backdrop-filter: blur(14px) saturate(1.3);
  transition:
    background 0.8s ease,
    color 0.8s ease,
    border-color 0.8s ease;
}

.brand {
  margin: 0;
  font-size: 26px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: #fff;
  text-shadow:
    0 2px 0 rgba(90, 60, 140, 0.25),
    0 6px 20px rgba(90, 60, 140, 0.25);
  padding: 4px 4px 2px;
  pointer-events: none;
}

.muted {
  color: var(--ink-soft);
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  background: rgba(255, 255, 255, 0.85);
  box-shadow: inset 0 0 0 1.5px rgba(58, 46, 77, 0.08);
}
.chip--level {
  background: linear-gradient(135deg, #ffd35c, #ffb13b);
  color: #6b4200;
  box-shadow: none;
}
.chip--stage {
  background: #efe6ff;
  color: #6b4fc4;
  box-shadow: none;
}
.chip--btn {
  cursor: pointer;
  transition: transform 0.15s ease;
}
.chip--btn:hover {
  transform: translateY(-1px);
}
.chip--btn.is-on {
  background: var(--pink);
  color: white;
  box-shadow: none;
}

/* ---------- Pet card ---------- */

.pet-card {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 12px 16px 12px 12px;
  width: 300px;
}

.avatar {
  width: 64px;
  height: 64px;
  border-radius: 20px;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 35% 30%, #fff, #ffe3ef 70%);
  box-shadow: inset 0 0 0 2px rgba(255, 111, 163, 0.18);
  flex: none;
}

.pet-meta {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.pet-name-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.pet-name {
  font-size: 21px;
  font-weight: 700;
  line-height: 1.05;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pet-sub {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
}

.xp {
  height: 7px;
  border-radius: 99px;
  background: rgba(58, 46, 77, 0.1);
  overflow: hidden;
}
.xp-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ffd35c, #ff9fce);
  transition: width 0.6s cubic-bezier(0.2, 0.9, 0.3, 1.2);
}

.mood {
  font-size: 13px;
  color: var(--ink-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ---------- Stats ---------- */

.utility {
  display: flex;
  gap: 8px;
}

.icon-btn {
  width: 40px;
  height: 40px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: var(--card);
  border: 1.5px solid var(--card-line);
  box-shadow: var(--shadow);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  transition:
    transform 0.15s ease,
    background 0.3s ease;
}
.icon-btn:hover {
  transform: translateY(-1px);
  background: var(--card-strong);
}
.icon-btn:active {
  transform: scale(0.94);
}
.icon-btn.is-off {
  color: var(--ink-soft);
  opacity: 0.8;
}
.icon-btn.is-active {
  background: #fff;
  color: #6b4fc4;
}
.icon-btn.tiny {
  width: 24px;
  height: 24px;
  border-radius: 8px;
  box-shadow: none;
  background: rgba(255, 255, 255, 0.6);
  border: 0;
  color: var(--ink-soft);
}

.stats-card {
  width: 236px;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.stat {
  display: flex;
  align-items: center;
  gap: 10px;
}

.stat-icon {
  width: 28px;
  height: 28px;
  flex: none;
  border-radius: 10px;
  display: grid;
  place-items: center;
  color: #fff;
  background: var(--c);
  box-shadow: 0 3px 8px -3px var(--c);
}

.stat-body {
  flex: 1;
  min-width: 0;
}

.stat-label {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  font-weight: 600;
  margin-bottom: 3px;
}

.stat-val {
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}

.bar {
  height: 8px;
  border-radius: 99px;
  background: rgba(58, 46, 77, 0.1);
  overflow: hidden;
}
.bar-fill {
  height: 100%;
  border-radius: inherit;
  background: var(--c);
  transition: width 0.5s ease;
}

.stat.is-low .stat-icon {
  animation: throb 1s ease-in-out infinite;
}
.stat.is-low .bar-fill {
  background: repeating-linear-gradient(-45deg, var(--c) 0 6px, color-mix(in srgb, var(--c) 70%, white) 6px 12px);
  background-size: 17px 17px;
  animation: stripes 0.8s linear infinite;
}
.stat.is-low .stat-val {
  color: #e2536f;
}

@keyframes throb {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.14);
  }
}
@keyframes stripes {
  to {
    background-position: 17px 0;
  }
}

.poop-nudge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 12px;
  border-radius: 999px;
  background: #fff4e6;
  color: #8a5a36;
  font-weight: 700;
  font-size: 13px;
  box-shadow: var(--shadow);
  animation: wiggle 2.4s ease-in-out infinite;
}

@keyframes wiggle {
  0%,
  86%,
  100% {
    transform: rotate(0);
  }
  90% {
    transform: rotate(-8deg);
  }
  95% {
    transform: rotate(8deg);
  }
}

/* ---------- Bottom ---------- */

.hud-bottom {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  pointer-events: none;
}

.panel-slot {
  width: 100%;
  display: flex;
  justify-content: center;
  pointer-events: none;
}

.dock {
  display: flex;
  gap: 6px;
  padding: 8px;
  border-radius: 28px;
  background: var(--card);
  border: 1.5px solid var(--card-line);
  box-shadow: var(--shadow);
  backdrop-filter: blur(14px) saturate(1.3);
  -webkit-backdrop-filter: blur(14px) saturate(1.3);
  transition: background 0.8s ease;
}

.dock-btn {
  position: relative;
  width: 76px;
  padding: 8px 4px 7px;
  border-radius: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  transition:
    transform 0.18s cubic-bezier(0.3, 1.6, 0.5, 1),
    background 0.2s ease;
}
.dock-btn:hover:not(:disabled) {
  background: color-mix(in srgb, var(--c) 12%, transparent);
  transform: translateY(-3px);
}
.dock-btn:active:not(:disabled) {
  transform: scale(0.93);
}
.dock-btn:disabled {
  opacity: 0.38;
  cursor: not-allowed;
}

.dock-icon {
  width: 46px;
  height: 46px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  color: #fff;
  background: linear-gradient(160deg, color-mix(in srgb, var(--c) 78%, white), var(--c));
  box-shadow:
    0 6px 14px -6px var(--c),
    inset 0 -3px 0 rgba(0, 0, 0, 0.1);
}

.dock-label {
  font-size: 13px;
  font-weight: 600;
}

.dock-btn.is-active {
  background: color-mix(in srgb, var(--c) 18%, white);
}
.dock-btn.is-active .dock-icon {
  transform: translateY(-2px) rotate(-6deg);
}
.dock-btn.is-pulse .dock-icon {
  animation: throb 0.9s ease-in-out infinite;
}

.dock-badge {
  position: absolute;
  top: 3px;
  right: 10px;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: 99px;
  background: #8a5a36;
  color: white;
  font-size: 12px;
  font-weight: 700;
  display: grid;
  place-items: center;
  border: 2px solid white;
  animation: pop-in 0.35s cubic-bezier(0.3, 1.6, 0.5, 1);
}

/* ---------- Panels ---------- */

.panel {
  width: min(760px, 100%);
  padding: 12px 14px 14px;
  animation: slide-up 0.32s cubic-bezier(0.2, 1.2, 0.4, 1);
}

@keyframes slide-up {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.98);
  }
}

.panel-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}
.panel-head .icon-btn {
  width: 32px;
  height: 32px;
  border-radius: 11px;
  box-shadow: none;
  margin-left: auto;
  flex: none;
}

.panel-title {
  font-size: 17px;
  font-weight: 700;
  white-space: nowrap;
}

.panel-hint {
  font-size: 13px;
  color: var(--ink-soft);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.food-row {
