.food-card:active:not(.is-locked) {
  transform: scale(0.95);
}
.food-card.is-lifted {
  opacity: 0.35;
  transform: scale(0.92);
}

.food-icon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  filter: drop-shadow(0 3px 3px rgba(60, 40, 90, 0.18));
  pointer-events: none;
}

.food-name {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.1;
  text-align: center;
  white-space: nowrap;
}

.food-chips {
  display: flex;
  gap: 4px;
  font-size: 11px;
  font-weight: 700;
  min-height: 15px;
}
.food-chip {
  display: inline-flex;
  align-items: center;
  gap: 1px;
}

.food-fav {
