}
.food-card.is-locked .food-icon,
.food-card.is-locked .food-name,
.food-card.is-locked .food-chips,
.food-card.is-locked .acc-slot {
  filter: grayscale(1) opacity(0.35);
}

.food-lock {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  font-size: 12px;
  font-weight: 700;
  color: #6b5a80;
}

.food-cooldown {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  display: grid;
  place-items: center;
  background: conic-gradient(rgba(58, 46, 77, 0.45) var(--p), rgba(58, 46, 77, 0.12) 0);
  color: white;
  font-weight: 700;
  font-size: 16px;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.35);
}

.acc-card.is-on {
  box-shadow:
    0 6px 14px -8px rgba(107, 79, 196, 0.6),
    inset 0 0 0 2.5px #a98bff;
  background: #f6f1ff;
}
.acc-slot {
  font-size: 11px;
  font-weight: 600;
  color: var(--ink-soft);
  text-transform: capitalize;
}
.acc-card.is-on .acc-slot {
  color: #6b4fc4;
}

.mode-bar {
  display: flex;
  align-items: center;
  gap: 16px;
  width: min(620px, 100%);
  padding: 12px 14px 12px 18px;
}

.mode-copy {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.mode-copy .panel-hint {
  white-space: normal;
}

.mode-meter {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 150px;
  font-weight: 700;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}
.mode-meter .bar {
  flex: 1;
  height: 10px;
}

.rally {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 70px;
}
.rally-num {
  font-size: 30px;
  font-weight: 700;
  line-height: 1;
  color: var(--pink);
  animation: pop-in 0.35s cubic-bezier(0.3, 1.8, 0.5, 1);
}
.rally-label {
  font-size: 12px;
  color: var(--ink-soft);
  white-space: nowrap;
}

.btn {
  padding: 10px 18px;
  border-radius: 14px;
  background: #fff;
  font-weight: 700;
  box-shadow:
    0 4px 10px -6px rgba(60, 40, 90, 0.4),
    inset 0 0 0 1.5px rgba(58, 46, 77, 0.08);
  transition: transform 0.15s cubic-bezier(0.3, 1.6, 0.5, 1);
  white-space: nowrap;
}
.btn:hover {
  transform: translateY(-2px);
}
.btn:active {
  transform: scale(0.96);
}
.btn.primary {
  background: linear-gradient(160deg, #ff8fbb, var(--pink));
  color: #fff;
  box-shadow:
    0 8px 16px -8px var(--pink),
    inset 0 -3px 0 rgba(0, 0, 0, 0.1);
}
.btn.danger {
  background: #fff0f2;
  color: #d23a5a;
}
.btn.danger.is-confirm {
  background: #e2536f;
  color: #fff;
}
.btn.wide {
  width: 100%;
}

/* ---------- Toasts ---------- */

.toasts {
  position: fixed;
  top: max(18px, env(safe-area-inset-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  pointer-events: none;
  z-index: 30;
  width: min(420px, calc(100% - 32px));
}

.toast {
  padding: 9px 16px;
  border-radius: 999px;
  background: var(--card-strong);
  box-shadow: var(--shadow);
  font-weight: 600;
  font-size: 14px;
  text-align: center;
  animation: toast-in 0.4s cubic-bezier(0.3, 1.6, 0.5, 1);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.toast--good {
  background: #eafff0;
  color: #2c7a45;
}
.toast--warn {
  background: #fff1e6;
  color: #b4521f;
}
.toast--level {
  background: linear-gradient(135deg, #fff6d6, #ffe6f1);
  color: #9a5a00;
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(-14px) scale(0.9);
  }
}

@keyframes pop-in {
  from {
    transform: scale(0.3);
    opacity: 0;
  }
}

/* ---------- 3D-anchored bubbles ---------- */

.pet-bubble {
  position: relative;
  transform-origin: 50% 100%;
  animation: bubble-in 0.35s cubic-bezier(0.3, 1.7, 0.5, 1);
  white-space: nowrap;
  font-family: "Fredoka Variable", "Fredoka", system-ui, sans-serif;
  pointer-events: none;
}

.pet-bubble::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -7px;
  width: 14px;
  height: 14px;
  background: #fff;
  transform: translateX(-50%) rotate(45deg);
  border-radius: 3px;
  z-index: -1;
}

.pet-bubble--icon,
.pet-bubble--need {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: #fff;
  display: grid;
  place-items: center;
  box-shadow: 0 8px 18px -8px rgba(60, 40, 90, 0.45);
}

.pet-bubble--need {
  animation:
    bubble-in 0.35s cubic-bezier(0.3, 1.7, 0.5, 1),
    bob 1.6s ease-in-out 0.35s infinite;
}

.pet-bubble--text {
  padding: 7px 14px;
  border-radius: 999px;
  background: #fff;
  color: var(--ink);
  font-weight: 700;
  font-size: 17px;
  box-shadow: 0 8px 18px -8px rgba(60, 40, 90, 0.45);
}

@keyframes bubble-in {
  from {
    transform: scale(0.2) translateY(10px);
    opacity: 0;
  }
}

@keyframes bob {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-5px);
  }
}

.float-layer {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}

.float-anchor {
  position: absolute;
  left: 0;
  top: 0;
  visibility: hidden;
  will-change: transform;
}

.float-anchor > .float-text {
  position: absolute;
  left: 0;
  top: 0;
  translate: -50% -50%;
}

.float-text {
  font-family: "Fredoka Variable", "Fredoka", system-ui, sans-serif;
  font-weight: 700;
  font-size: 18px;
  white-space: nowrap;
  pointer-events: none;
  text-shadow:
    0 0 3px #fff,
    0 0 3px #fff,
    0 2px 0 #fff,
    0 0 10px rgba(255, 255, 255, 0.9);
  animation: float-up 1.5s cubic-bezier(0.2, 0.8, 0.3, 1) forwards;
}

@keyframes float-up {
  0% {
    transform: translateY(8px) scale(0.5);
    opacity: 0;
  }
  15% {
    transform: translateY(0) scale(1.15);
    opacity: 1;
  }
  30% {
    transform: translateY(-6px) scale(1);
  }
  100% {
    transform: translateY(-58px) scale(0.95);
    opacity: 0;
  }
}

/* ---------- Egg ---------- */

.egg-hint {
  position: fixed;
  left: 50%;
  bottom: max(28px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  padding: 14px 24px;
  text-align: center;
  animation: slide-up 0.5s cubic-bezier(0.2, 1.2, 0.4, 1);
}
.egg-hint-title {
  font-weight: 700;
  font-size: 18px;
}
.egg-hint-copy {
  color: var(--ink-soft);
  font-size: 14px;
  margin-top: 2px;
}
.egg-dots {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-top: 10px;
}
.egg-dots span {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: rgba(58, 46, 77, 0.14);
  transition:
    background 0.3s ease,
    transform 0.3s cubic-bezier(0.3, 1.8, 0.5, 1);
}
.egg-dots span.is-on {
  background: var(--gold);
  transform: scale(1.25);
}

/* ---------- Modal / level up / settings ---------- */

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(58, 46, 77, 0.28);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  animation: fade-in 0.25s ease;
}
@keyframes fade-in {
  from {
    opacity: 0;
  }
}

.modal {
  width: min(400px, 100%);
  padding: 24px 22px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  background: var(--card-strong);
  animation: pop-in 0.4s cubic-bezier(0.3, 1.5, 0.5, 1);
  user-select: text;
}
.modal-cow {
  width: 96px;
  height: 96px;
  border-radius: 32px;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 35% 30%, #fff, #ffe3ef 70%);
  margin-top: -64px;
  box-shadow: var(--shadow);
  animation: bob 2s ease-in-out infinite;
}
.modal-title {
  margin: 14px 0 4px;
  font-size: 22px;
}
.modal-copy {
  margin: 0 0 14px;
  color: var(--ink-soft);
}
.name-input {
  width: 100%;
  font: inherit;
  font-size: 22px;
  font-weight: 700;
  text-align: center;
  color: var(--ink);
  padding: 10px 14px;
  border-radius: 16px;
  border: 2px solid #ffd0e2;
  background: #fff;
  outline: none;
}
.name-input:focus {
  border-color: var(--pink);
}
.name-ideas {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  margin: 12px 0 16px;
}

.levelup {
  position: fixed;
  left: 50%;
  top: 22%;
  transform: translateX(-50%);
  z-index: 35;
  width: min(340px, calc(100% - 32px));
  padding: 20px 20px 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
  background: linear-gradient(160deg, rgba(255, 250, 230, 0.95), rgba(255, 234, 244, 0.95));
  animation: levelup-in 0.6s cubic-bezier(0.3, 1.5, 0.5, 1);
}
@keyframes levelup-in {
  from {
    opacity: 0;
    transform: translateX(-50%) scale(0.5) rotate(-6deg);
  }
}
.levelup-star {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  background: linear-gradient(160deg, #ffd35c, #ffab2e);
  box-shadow: 0 8px 20px -8px #ffab2e;
  margin-top: -46px;
  animation: spin-slow 6s linear infinite;
}
@keyframes spin-slow {
  to {
    transform: rotate(360deg);
  }
}
.levelup-title {
  font-size: 28px;
  font-weight: 700;
  color: #9a5a00;
}
.levelup-stage {
  font-weight: 600;
}
.levelup-unlocks {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: center;
  align-items: center;
  font-size: 13px;
}

.settings {
  position: fixed;
  top: calc(max(16px, env(safe-area-inset-top)) + 50px);
  right: max(18px, env(safe-area-inset-right));
  z-index: 25;
  width: min(300px, calc(100% - 36px));
  padding: 14px;
  background: var(--card-strong);
  animation: slide-up 0.3s cubic-bezier(0.2, 1.2, 0.4, 1);
}
.journal {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  margin-bottom: 12px;
}
.journal div {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 2px;
  border-radius: 14px;
  background: #f7f3ff;
}
.journal b {
  font-size: 20px;
}
.journal span {
  font-size: 11px;
  color: var(--ink-soft);
  text-align: center;
}
.shortcuts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 10px;
  margin-bottom: 12px;
  font-size: 12px;
  color: var(--ink-soft);
}
kbd {
  font-family: inherit;
  font-weight: 700;
  font-size: 11px;
  padding: 1px 6px;
  border-radius: 6px;
  background: #fff;
  box-shadow: inset 0 -2px 0 rgba(58, 46, 77, 0.12), 0 0 0 1px rgba(58, 46, 77, 0.1);
  color: var(--ink);
}

/* ---------- Night / asleep ---------- */

.hud.is-asleep .card,
.hud.is-asleep .panel,
.hud.is-asleep .dock,
.hud.is-asleep .icon-btn {
  background: rgba(34, 32, 70, 0.62);
  border-color: rgba(160, 160, 255, 0.18);
  color: #e9e6ff;
}
.hud.is-asleep .muted,
.hud.is-asleep .mood,
.hud.is-asleep .panel-hint,
.hud.is-asleep .stat-val {
  color: #b3add6;
}
.hud.is-asleep .bar,
.hud.is-asleep .xp {
  background: rgba(255, 255, 255, 0.12);
}
.hud.is-asleep .avatar {
  background: radial-gradient(circle at 35% 30%, #5a5892, #34325f 70%);
}
.hud.is-asleep .chip:not(.chip--level):not(.chip--stage) {
  background: rgba(255, 255, 255, 0.12);
}

/* ---------- Responsive ---------- */

@media (max-width: 760px) {
  .hud {
    padding: max(10px, env(safe-area-inset-top)) max(10px, env(safe-area-inset-right)) max(10px, env(safe-area-inset-bottom))
      max(10px, env(safe-area-inset-left));
  }
  .hud-top {
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
  }
  .hud-left {
    gap: 8px;
  }
  .brand {
    font-size: 20px;
    padding-right: 140px;
  }
  .hud-right {
    align-items: stretch;
  }
  .utility {
    position: absolute;
    top: max(10px, env(safe-area-inset-top));
    right: max(10px, env(safe-area-inset-right));
    gap: 6px;
  }
  .utility .icon-btn {
    width: 36px;
    height: 36px;
    border-radius: 12px;
  }
  .pet-card {
    width: 100%;
    padding: 8px 12px 8px 8px;
    gap: 10px;
  }
  .avatar {
    width: 48px;
    height: 48px;
    border-radius: 16px;
  }
  .avatar svg {
    width: 36px;
    height: 36px;
  }
  .pet-name {
    font-size: 18px;
  }
  .mood {
    display: none;
  }
  .stats-card {
    width: 100%;
    flex-direction: row;
    gap: 8px;
    padding: 8px 10px;
  }
  .stat {
    flex: 1;
    flex-direction: column;
    gap: 4px;
  }
  .stat-body {
    width: 100%;
  }
  .stat-label span:first-child {
    display: none;
  }
  .stat-label {
    justify-content: center;
    margin-bottom: 2px;
    font-size: 11px;
  }
  .stat-icon {
    width: 24px;
    height: 24px;
    border-radius: 8px;
  }
  .bar {
    height: 6px;
  }
  .poop-nudge {
    align-self: flex-end;
  }
  .dock {
    gap: 2px;
    padding: 6px;
    border-radius: 24px;
    width: 100%;
    justify-content: space-between;
  }
  .dock-btn {
    width: auto;
    flex: 1;
    padding: 6px 2px;
  }
  .dock-icon {
    width: 40px;
    height: 40px;
    border-radius: 14px;
  }
  .dock-icon svg {
    width: 22px;
    height: 22px;
  }
  .dock-label {
    font-size: 11.5px;
  }
  .dock-badge {
    right: 4px;
  }
  .panel-hint {
    display: none;
  }
  .mode-copy .panel-hint {
    display: block;
    font-size: 12px;
  }
  .mode-bar {
    gap: 10px;
    padding: 10px 12px;
  }
  .mode-meter {
    width: 96px;
  }
  .food-card {
    width: 82px;
  }
  .settings {
    top: calc(max(10px, env(safe-area-inset-top)) + 46px);
    right: max(10px, env(safe-area-inset-right));
  }
}

@media (max-height: 560px) and (min-width: 761px) {
  .stats-card {
    gap: 4px;
    padding: 8px 12px;
  }
  .pet-card .mood {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

