.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(58, 46, 77, 0.28);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  animation: fade-in 0.25s ease;
}
@keyframes fade-in {
  from {
    opacity: 0;
  }
}

.modal {
  width: min(400px, 100%);
  padding: 24px 22px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  background: var(--card-strong);
  animation: pop-in 0.4s cubic-bezier(0.3, 1.5, 0.5, 1);
  user-select: text;
}
.modal-cow {
  width: 96px;
  height: 96px;
  border-radius: 32px;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 35% 30%, #fff, #ffe3ef 70%);
  margin-top: -64px;
  box-shadow: var(--shadow);
  animation: bob 2s ease-in-out infinite;
}
.modal-title {
  margin: 14px 0 4px;
  font-size: 22px;
}
.modal-copy {
  margin: 0 0 14px;
  color: var(--ink-soft);
}
.name-input {
  width: 100%;
  font: inherit;
  font-size: 22px;
  font-weight: 700;
  text-align: center;
  color: var(--ink);
  padding: 10px 14px;
  border-radius: 16px;
  border: 2px solid #ffd0e2;
  background: #fff;
  outline: none;
}
.name-input:focus {
  border-color: var(--pink);
}
.name-ideas {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  margin: 12px 0 16px;
}

.levelup {
  position: fixed;
  left: 50%;
  top: 22%;
  transform: translateX(-50%);
  z-index: 35;
  width: min(340px, calc(100% - 32px));
  padding: 20px 20px 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
