  }
  .avatar {
    width: 48px;
    height: 48px;
    border-radius: 16px;
  }
  .avatar svg {
    width: 36px;
    height: 36px;
  }
  .pet-name {
    font-size: 18px;
  }
  .mood {
    display: none;
  }
  .stats-card {
