    gap: 8px;
    padding: 8px 10px;
  }
  .stat {
    flex: 1;
    flex-direction: column;
    gap: 4px;
  }
  .stat-body {
    width: 100%;
  }
  .stat-label span:first-child {
    display: none;
  }
  .stat-label {
    justify-content: center;
    margin-bottom: 2px;
    font-size: 11px;
  }
  .stat-icon {
    width: 24px;
    height: 24px;
    border-radius: 8px;
  }
  .bar {
    height: 6px;
  }
  .poop-nudge {
    align-self: flex-end;
  }
  .dock {
    gap: 2px;
    padding: 6px;
    border-radius: 24px;
    width: 100%;
    justify-content: space-between;
  }
  .dock-btn {
    width: auto;
    flex: 1;
    padding: 6px 2px;
  }
  .dock-icon {
    width: 40px;
    height: 40px;
    border-radius: 14px;
  }
  .dock-icon svg {
    width: 22px;
    height: 22px;
  }
  .dock-label {
    font-size: 11.5px;
  }
  .dock-badge {
    right: 4px;
  }
  .panel-hint {
    display: none;
  }
  .mode-copy .panel-hint {
    display: block;
    font-size: 12px;
  }
  .mode-bar {
    gap: 10px;
    padding: 10px 12px;
  }
  .mode-meter {
    width: 96px;
  }
  .food-card {
    width: 82px;
  }
  .settings {
    top: calc(max(10px, env(safe-area-inset-top)) + 46px);
    right: max(10px, env(safe-area-inset-right));
  }
}

@media (max-height: 560px) and (min-width: 761px) {
