            <group key={k as string} ref={bind(k as string)} position={[x as number, y as number, z as number]}>
              <mesh material={m.fur} position={[0, -0.2, 0]} castShadow>
                <capsuleGeometry args={[0.11, 0.16, 8, 16]} />
