            </group>
          ))}

          <group ref={bind("tail")} position={[0, 0.8, -0.7]}>
            <mesh material={m.fur} position={[0, -0.17, 0]}>
              <capsuleGeometry args={[0.028, 0.3, 4, 8]} />
