function ModeBar() {
  const mode = useGame((s) => s.mode);
  const asleep = useGame((s) => s.asleep);
  const name = useGame((s) => s.name);
  const rally = useGame((s) => s.rally);
  const best = useGame((s) => s.bestRally);
