        <button type="button" className="icon-btn" onClick={() => setPanel(null)} aria-label="Close settings">
          <IconClose size={16} />
        </button>
      </div>
      <div className="journal">
        <div>
          <b>{totals.fed}</b>
          <span>snacks</span>
        </div>
        <div>
          <b>{totals.pets}</b>
          <span>pets</span>
        </div>
        <div>
          <b>{totals.cleans}</b>
          <span>baths</span>
        </div>
        <div>
          <b>{best}</b>
          <span>best rally</span>
        </div>
      </div>
      <div className="shortcuts">
        <span>
          <kbd>F</kbd> feed
        </span>
        <span>
          <kbd>P</kbd> play
        </span>
        <span>
          <kbd>C</kbd> clean
        </span>
        <span>
          <kbd>S</kbd> sleep
        </span>
        <span>
          <kbd>W</kbd> style
        </span>
        <span>
          <kbd>M</kbd> mute
        </span>
      </div>
      <button
        type="button"
        className={`btn danger wide${confirm ? " is-confirm" : ""}`}
        onClick={() => {
          if (!confirm) {
            setConfirm(true);
            window.setTimeout(() => setConfirm(false), 3000);
            return;
          }
          reset();
        }}
      >
        {confirm ? "Tap again to say goodbye" : "Start over with a new egg"}
      </button>
