function LevelUpCard() {
  const info = useGame((s) => s.levelUp);
  const name = useGame((s) => s.name);
  const dismiss = useGame((s) => s.dismissLevelUp);
  useEffect(() => {
    if (!info) return;
    const id = window.setTimeout(dismiss, 7000);
    return () => window.clearTimeout(id);
