  box-shadow: var(--shadow);
  animation: bob 2s ease-in-out infinite;
}
.modal-title {
  margin: 14px 0 4px;
  font-size: 22px;
}
.modal-copy {
  margin: 0 0 14px;
  color: var(--ink-soft);
}
.name-input {
  width: 100%;
  font: inherit;
  font-size: 22px;
  font-weight: 700;
  text-align: center;
  color: var(--ink);
  padding: 10px 14px;
  border-radius: 16px;
  border: 2px solid #ffd0e2;
  background: #fff;
  outline: none;
}
.name-input:focus {
  border-color: var(--pink);
}
.name-ideas {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  margin: 12px 0 16px;
}

.levelup {
  position: fixed;
  left: 50%;
  top: 22%;
  transform: translateX(-50%);
  z-index: 35;
  width: min(340px, calc(100% - 32px));
  padding: 20px 20px 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
  background: linear-gradient(160deg, rgba(255, 250, 230, 0.95), rgba(255, 234, 244, 0.95));
  animation: levelup-in 0.6s cubic-bezier(0.3, 1.5, 0.5, 1);
}
@keyframes levelup-in {
  from {
    opacity: 0;
    transform: translateX(-50%) scale(0.5) rotate(-6deg);
  }
}
.levelup-star {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  background: linear-gradient(160deg, #ffd35c, #ffab2e);
  box-shadow: 0 8px 20px -8px #ffab2e;
  margin-top: -46px;
  animation: spin-slow 6s linear infinite;
}
@keyframes spin-slow {
  to {
    transform: rotate(360deg);
  }
}
.levelup-title {
  font-size: 28px;
  font-weight: 700;
  color: #9a5a00;
}
.levelup-stage {
  font-weight: 600;
}
.levelup-unlocks {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: center;
  align-items: center;
