}
.shortcuts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 10px;
  margin-bottom: 12px;
  font-size: 12px;
  color: var(--ink-soft);
}
kbd {
  font-family: inherit;
  font-weight: 700;
  font-size: 11px;
  padding: 1px 6px;
  border-radius: 6px;
  background: #fff;
  box-shadow: inset 0 -2px 0 rgba(58, 46, 77, 0.12), 0 0 0 1px rgba(58, 46, 77, 0.1);
