    const palette = ["#ff5d73", "#ffffff", "#ffc93c", "#ffffff", "#3fb8ff", "#ffffff"].map((c) => new Color(c));
    const cap = new Color("#ffffff");
    for (let i = 0; i < pos.count; i += 3) {
