    const toPet = away.clone().negate().normalize();
    const ang = rand(-0.9, 0.9);
    const c = Math.cos(ang);
    const s = Math.sin(ang);
    const dir = new Vector3(toPet.x * c - toPet.z * s, 0, toPet.x * s + toPet.z * c);
