    emit("dust", tmp.set(p.x, 0.1, p.z), { count: 6, speed: 0.8, up: 0.3, size: 0.1, life: 0.6, color: "#f1e3c8" });
    g.cleanPoop(p.id);
    delete document.body.dataset.hover;
  };

