                ))}

                <mesh material={m.muzzle} position={[0, -0.15, 0.33]} scale={[0.34, 0.24, 0.22]} castShadow>
                  <sphereGeometry args={[1, 28, 20]} />
                </mesh>
                {[-1, 1].map((sd) => (
