const TARGET = new Vector3(0, 0.55, 0);

function CameraRig() {
  const ref = useRef<ComponentRef<typeof OrbitControls>>(null);
  const camera = useThree((s) => s.camera);
  const width = useThree((s) => s.size.width);
  const height = useThree((s) => s.size.height);
  const mode = useGame((s) => s.mode);

  useEffect(() => {
    controls.enabled = (v) => {
      if (ref.current) ref.current.enabled = v && useGame.getState().mode !== "clean";
    };
  }, []);

  useEffect(() => {
    if (ref.current) ref.current.enabled = mode !== "clean";
  }, [mode]);

  const shift = useRef(0);
  useFrame((state, dt) => {
    const { width: w, height: h } = state.size;
    const goal = MathUtils.clamp((ui.bottom - ui.top) / 2, -h * 0.2, h * 0.2);
    const next = shift.current + (goal - shift.current) * (1 - Math.exp(-Math.min(dt, 0.1) * 6));
    const cam = state.camera as PerspectiveCamera;
    if (Math.abs(next - shift.current) < 0.05 && cam.view?.fullHeight === h && cam.view.fullWidth === w) return;
    shift.current = next;
    cam.setViewOffset(w, h, 0, next, w, h);
  });

  useEffect(() => {
    const aspect = width / height;
    const dist = aspect < 0.62 ? 18.5 : aspect < 0.85 ? 16 : aspect < 1.2 ? 13 : aspect < 1.6 ? 10.8 : 9.9;
    const target = TARGET.clone();
    if (aspect < 0.85) target.y = 0.2;
    const dir = new Vector3(0, 0.4, 1).normalize();
    camera.position.copy(dir.multiplyScalar(dist).add(target));
    if (ref.current) {
      ref.current.target.copy(target);
      ref.current.update();
    }
  }, [width, height, camera]);

  return (
    <OrbitControls
      ref={ref}
      target={TARGET}
      enablePan={false}
      enableDamping
      dampingFactor={0.08}
      minDistance={6.5}
      maxDistance={21}
      minPolarAngle={0.55}
      maxPolarAngle={1.36}
      minAzimuthAngle={-1.15}
      maxAzimuthAngle={1.15}
      rotateSpeed={0.55}
      zoomSpeed={0.7}
    />
  );
}

